            for (PrereqMemberRequest m : group) {
                Map<String, Object> member = new LinkedHashMap<>();
                member.put("incidentKey", m.incidentKey());
                member.put("taskKey", m.taskKey());
                member.put("expectedTaskVersion", m.expectedTaskVersion());
                members.add(member);
