                                .filter(m -> "DONE".equals(m.status()))
                                .min(Comparator.comparing(MemberRow::incidentKey)
                                        .thenComparing(MemberRow::taskKey))
                                .orElseThrow();
                        for (MemberRow m : e.getValue()) {
